            </template>
          </el-table-column>
          <el-table-column label="操作" fixed="right" width="200" align="center">
            <template #default="{ row }">
              <div class="action-buttons">
                <el-button link type="primary" @click="handleView(row)" class="action-btn">详情</el-button>
                <template v-if="row.status === 'pending' && isMyTurn(row)">
                  <el-button link type="success" @click="handleProcess(row, 'approved')" class="action-btn">通过</el-button>
                  <el-button link type="danger" @click="handleProcess(row, 'rejected')" class="action-btn">驳回</el-button>
                </template>
                <template v-if="activeApps.find(a => a.code === row.type)?.requires_manual_return && row.status === 'approved' && !isApprover">
                  <el-button link type="warning" @click="handleReturn(row)" class="action-btn">归还</el-button>
                </template>
                <el-tag v-if="activeApps.find(a => a.code === row.type)?.requires_manual_return && row.status === 'completed'" type="info" size="small" class="ml-2">已归还</el-tag>
              </div>
            </template>
          </el-table-column>
        </el-table>
        
        <div v-if="approvals.length === 0 && !loading" class="empty-placeholder">
          <el-empty description="暂无审批记录" :image-size="100" />
        </div>
      </div>
    </div>

    <!-- 审批详情对话框 -->
    <el-dialog v-model="dialogVisible" title="审批详情" width="680px" :append-to-body="true" class="feishu-dialog">
      <div v-if="selectedApproval" class="detail-container">
        <!-- 基本信息卡片 -->
        <div class="detail-section">
          <div class="section-header">
            <div class="header-info">
              <span class="status-badge" :class="selectedApproval.status">
                {{ getStatusText(selectedApproval.status, selectedApproval.type) }}
              </span>
              <h3>{{ selectedApproval.title }}</h3>
            </div>
          </div>
          
          <div class="info-grid">
            <div class="info-item">
              <span class="info-label">申请人</span>
              <span class="info-value">{{ selectedApproval.applicant_name }}</span>
            </div>
            <div class="info-item">
              <span class="info-label">审批类型</span>
              <span class="info-value">{{ getTypeText(selectedApproval.type) }}</span>
            </div>
            <div class="info-item">
              <span class="info-label">当前审批人</span>
              <span class="info-value">{{ selectedApproval.approver_name || '未指定' }}</span>
            </div>
            <div class="info-item">
              <span class="info-label">申请时间</span>
              <span class="info-value">{{ formatDate(selectedApproval.created_at) }}</span>
            </div>
          </div>

          <!-- 请假时长 -->
          <div class="info-item full-width" v-if="selectedApproval.extra_data && selectedApproval.extra_data.leave_days">
            <span class="info-label">请假时长</span>
            <el-tag size="small" type="warning">{{ selectedApproval.extra_data.leave_days }} 天</el-tag>
          </div>
          
          <!-- 申请内容 -->
          <div class="content-section">
            <span class="info-label">申请内容</span>
