<script setup>
import { ref, onMounted, computed, reactive, watch } from 'vue'
import { CircleCheck, Plus, Calendar, Box, ShoppingCart, Warning, Document, ChatDotRound } from '@element-plus/icons-vue'
import api from '@/api'
import dayjs from 'dayjs'
import { ElMessage, ElMessageBox } from 'element-plus'
import DynamicForm from '@/components/DynamicForm.vue'

const activeTab = ref('pending')
const approvals = ref([])
const users = ref([])
const loading = ref(false)
const submitting = ref(false)
const dialogVisible = ref(false)
const createVisible = ref(false)
const selectAppVisible = ref(false)
const selectedApproval = ref(null)
const currentUser = ref(null)
const activeApps = ref([])
const selectedApp = ref(null)
const meta = ref({ instance_statuses: [], apps: [] })

const instanceStatusLabelMap = computed(() => {
  const m = {}
  for (const s of (meta.value.instance_statuses || [])) {
    if (s && s.code) m[s.code] = s.label
  }
  return m
})

const appNameMap = computed(() => {
  const m = {}
  for (const a of (meta.value.apps || [])) {
    if (a && a.code) m[a.code] = a.name
  }
  return m
})

const currentProfileId = computed(() => currentUser.value?.id)
const isReady = computed(() => Boolean(currentProfileId.value))
const fetchSeq = ref(0)

const isApprover = computed(() => {
  const role = currentUser.value?.role
  const permissions = currentUser.value?.permissions || []
  return ['管理员', '教师'].includes(role) || permissions.includes('approve')
})
const pendingCount = computed(() => approvals.value.filter(a => a.status === 'pending').length)

const getHeaderSubtitle = () => {
  if (isApprover.value) {
    return pendingCount.value > 0 ? `您有 ${pendingCount.value} 条待处理审批` : '暂无待处理审批'
  }
  return '管理您的申请记录'
}

const fetchApprovals = async () => {
  if (!isReady.value) return

  loading.value = true
  approvals.value = []
  const seq = ++fetchSeq.value
  try {
    let params = {}
    if (activeTab.value === 'pending') {
      params.status = 'pending'
      if (isApprover.value) params.approver = currentProfileId.value
      else params.applicant = currentProfileId.value
    } else if (activeTab.value === 'processed') {
      params.status__in = 'approved,rejected,completed'
      if (isApprover.value) params.approver = currentProfileId.value
      else params.applicant = currentProfileId.value
    } else {
      params.applicant = currentProfileId.value
    }
    const res = await api.getApprovals(params)
    if (seq === fetchSeq.value) approvals.value = res.data.results || res.data || []
  } catch (error) {
    ElMessage.error('获取审批列表失败')
  } finally {
    if (seq === fetchSeq.value) loading.value = false
  }
}

const getIcon = (iconName) => {
  const map = {
    'el-icon-calendar': Calendar,
    'el-icon-box': Box,
    'el-icon-shopping-cart': ShoppingCart,
    'el-icon-warning': Warning,
    'el-icon-document': Document,
    'el-icon-chat-dot-round': ChatDotRound
  }
  return map[iconName] || Calendar
}

const fetchActiveApps = async () => {
  try {
    const res = await api.getLowCodeApps()
    activeApps.value = res.data || []
  } catch (error) {
    console.error('获取应用列表失败')
  }
}

const fetchUsers = async () => {
  try {
    const res = await api.getUsers({ role: 'teacher' })
    users.value = res.data.results || res.data || []
  } catch (error) {
    console.error('获取用户列表失败')
  }
}

const openCreateApproval = () => {
  selectAppVisible.value = true
}

const startAppApplication = (app) => {
  selectedApp.value = app
  selectAppVisible.value = false
  createVisible.value = true
}

const handleCreateSuccess = () => {
  createVisible.value = false
  fetchApprovals()
}

const handleTabClick = () => {
  fetchApprovals()
}

const handleView = (row) => {
  selectedApproval.value = row
  dialogVisible.value = true
}

const isMyTurn = (approval) => {
  if (!isApprover.value) return false
  if (currentUser.value?.permissions?.includes('config_business')) return true
  return Number(approval.approver) === Number(currentProfileId.value)
}

const handleProcess = (row, status) => {
  const actionText = status === 'approved' ? '批准' : '驳回'
  ElMessageBox.prompt(`请输入${actionText}意见`, actionText, {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
    inputPlaceholder: '可选意见...',
  }).then(async ({ value }) => {
    try {
      await api.processApproval(row.id, { 
        action: status, 
        comment: value, 
        instance_id: row.id,
        user_id: currentProfileId.value 
      })
      ElMessage.success(`已成功${actionText}`)
      dialogVisible.value = false
      fetchApprovals()
      if (window.dispatchEvent) {
        window.dispatchEvent(new CustomEvent('approval-updated'))
      }
    } catch (error) {
      ElMessage.error(api.getErrorMessage(error, '操作失败'))
    }
  })
}

const handleReturn = (row) => {
  ElMessageBox.confirm('确定已归还该设备吗？系统将自动恢复设备库存和状态。', '归还确认', {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
    type: 'warning'
  }).then(async () => {
    try {
      await api.returnLowCodeInstance({
        instance_id: row.id,
        user_id: currentProfileId.value
      })
      ElMessage.success('设备归还成功')
      fetchApprovals()
    } catch (error) {
      ElMessage.error(api.getErrorMessage(error, '归还操作失败'))
    }
  })
}

const formatDate = (date) => dayjs(date).format('YYYY-MM-DD HH:mm')
const getStatusText = (status, type) => {
  const appConfig = activeApps.value.find(a => a.code === type)
  const isBorrow = appConfig ? appConfig.requires_manual_return : (type === 'borrow' || type === 'equipment_borrow')
  
  if (isBorrow) {
    if (status === 'approved') return '借用中'
    if (status === 'completed') return '已归还'
  }
  return instanceStatusLabelMap.value[status] || status
}

const getFieldLabel = (key, type) => {
  const map = {
    leave_days: '请假天数',
    leave_type: '请假类型',
    leave_reason: '请假原因',
    purpose: '申请事由',
    content: '申请内容',
    equipment_id: '设备ID',
    quantity: '数量',
    start_date: '开始日期',
    end_date: '结束日期'
  }
  return map[key] || key
}

const getTypeText = (type) => {
  return appNameMap.value[type] || type
}
const getTypeTag = (type) => {
  const map = {
    borrow: 'primary',
    equipment_borrow: 'primary',
    equipment_purchase: 'warning',
    equipment_repair: 'danger',
    leave_business: 'success',
    leave_private: 'warning',
    other: 'info'
  }
  return map[type] || 'info'
}
const getRecordTimelineType = (status) => {
  if (status === 'approve' || status === 'approved' || status === 'completed') return 'success'
  if (status === 'reject' || status === 'rejected') return 'danger'
  return 'primary'
}
const getRecordTagType = (status) => {
  if (status === 'approve' || status === 'approved' || status === 'completed') return 'success'
  if (status === 'reject' || status === 'rejected') return 'danger'
  return 'info'
}

onMounted(() => {
  const userStr = localStorage.getItem('user')
  if (userStr) {
    currentUser.value = JSON.parse(userStr)
  }
  api.getMeta().then(r => { meta.value = r.data || {} }).catch(() => {})
  fetchUsers()
  fetchActiveApps()
})

watch([activeTab, currentProfileId], () => {
  fetchApprovals()
}, { immediate: true })
</script>

